farms = pd.read_csv('/app/dataset/farms.csv')
reg = pd.read_csv('/app/dataset/farm_registry.csv')
farms['farm_name_norm'] = farms['farm_name'].str.strip().str.lower()
reg['farm_name_norm'] = reg['farm_name'].str.strip().str.lower()
meta = reg.merge(farms[['farm_name_norm','timezone','installed_capacity_kw']], on='farm_name_norm', how='left').set_index('farm_id').to_dict(orient='index')
cfg = json.load(open('/app/dataset/sensors_calibration.json'))['enterprise_platform']['deployment_environments']['system_config']['farms']

maintenance = {
    'FARM_C': [(datetime(2024,3,16,8,0), datetime(2024,3,16,12,0))],
    'FARM_F': [(datetime(2024,3,15,12,0), datetime(2024,3,15,14,0))],
}

def sniff_encoding(path):
    with open(path,'rb') as f:
        h=f.read(4)
    return 'utf-16' if h.startswith((b'\xff\xfe', b'\xfe\xff')) else 'utf-8'

def parse_dt(s):
    s=str(s).strip()
    for fmt in STRICT_FORMATS:
        try:
            return datetime.strptime(s,fmt)
        except: pass
    return None

def parse_num(s, delim):
    s=str(s).strip()
    if s=='': return None
    if delim==';':
        s=s.replace('.','').replace(',','.')
    try: return float(s)
    except: return None

def compute(local_tz=True, drop_sentinels=False, cap_filter=None):
    out={}
    for farm_id, m in meta.items():
        path=f'/app/dataset/production_{farm_id}.csv'
        enc=sniff_encoding(path)
        with open(path,'r',encoding=enc,errors='replace') as f:
            lines=f.read().splitlines()
        delim=';' if lines[3].count(';')>lines[3].count(',') else ','
        df=pd.read_csv(path, skiprows=3, sep=delim, encoding=enc, dtype=str, keep_default_na=False).drop_duplicates()
        ts_col=df.columns[0]
        target=cfg[farm_id]['calibration_data']['value_column_name']
        offset=cfg[farm_id]['calibration_data']['calibration_offset']
        rtype=cfg[farm_id]['sensor_info']['reading_type'].lower()
        unit=cfg[farm_id]['sensor_info']['unit'].lower()
        tz=ZoneInfo(m['timezone'])
        # mode step in hours from valid timestamps after local/naive parsing, sorted unique
        ts_valid=[]
        for s in df[ts_col]:
            dt=parse_dt(s)
            if dt is not None:
                ts_valid.append(dt)
        ts_valid=sorted(set(ts_valid))
        diffs=[(b-a).total_seconds()/3600 for a,b in zip(ts_valid, ts_valid[1:]) if b>a]
        step=pd.Series(diffs).mode().iloc[0] if diffs else 0.0
        total=0.0
        # safety windows built from temp spikes in local time
        safety=[]
        temp_col='inverter_temperature_C'
        for _, row in df.iterrows():
            dt=parse_dt(row[ts_col])
            if dt is None:
                continue
            temp=parse_num(row.get(temp_col,''),delim)
            if temp is not None and temp>85.0:
                safety.append((dt, dt+timedelta(minutes=45)))
        for _, row in df.iterrows():
            local_dt=parse_dt(row[ts_col])
            if local_dt is None:
                continue
            raw=parse_num(row.get(target,''),delim)
            if raw is None:
                continue
            if drop_sentinels and raw in SENTINELS:
                continue
            true=raw-offset
            if true<0:
                continue
            if any(start <= local_dt < end for start,end in maintenance.get(farm_id,[])):
                continue
            if any(spike < local_dt <= end for spike,end in safety):
                continue
            if local_tz:
                dt_utc=local_dt.replace(tzinfo=tz).astimezone(timezone.utc)
            else:
                dt_utc=local_dt.replace(tzinfo=timezone.utc)
            if not (REPORT_START_UTC <= dt_utc < REPORT_END_UTC):
