REPORT_END_UTC = datetime(2024, 3, 16, 0, 0, 0, tzinfo=timezone.utc)
STRICT_TIMESTAMP_FORMATS = (
    "%Y-%m-%d %H:%M:%S",
    "%d.%m.%Y %H:%M:%S",
)
MONTHS = {
    "january": 1,
    "february": 2,
    "march": 3,
    "april": 4,
    "may": 5,
    "june": 6,
    "july": 7,
    "august": 8,
    "september": 9,
    "october": 10,
    "november": 11,
    "december": 12,
}
UNIT_TO_KWH = {
    "wh": 0.001,
    "kwh": 1.0,
    "mwh": 1000.0,
    "btu": 0.00029307107,
}
PHYSICAL_HEADROOM = 1.2


def sniff_encoding(path: Path) -> str:
    with path.open("rb") as handle:
        header = handle.read(4)
    if header.startswith((b"\xff\xfe", b"\xfe\xff")):
        return "utf-16"
    return "utf-8"


def detect_delimiter(path: Path, encoding: str) -> str:
    with path.open("r", encoding=encoding, errors="replace") as handle:
        lines = handle.read().splitlines()
    header_line = lines[3]
    return ";" if header_line.count(";") > header_line.count(",") else ","


def parse_timestamp(value: object) -> datetime | None:
    text = str(value).strip()
    if not text:
        return None
    for fmt in STRICT_TIMESTAMP_FORMATS:
        try:
            return datetime.strptime(text, fmt)
        except ValueError:
            continue
    return None


def parse_number(value: object, delimiter: str) -> float | None:
    text = str(value).strip()
    if not text:
        return None
    if delimiter == ";":
        text = text.replace(".", "").replace(",", ".")
    try:
        return float(text)
    except ValueError:
        return None


def normalize_name(value: str) -> str:
    return " ".join(value.strip().lower().split())


def load_farm_metadata() -> dict[str, dict[str, object]]:
    farms = pd.read_csv(DATASET_DIR / "farms.csv")
    registry = pd.read_csv(DATASET_DIR / "farm_registry.csv")
    farms["farm_name_norm"] = farms["farm_name"].map(normalize_name)
    registry["farm_name_norm"] = registry["farm_name"].map(normalize_name)
    merged = registry.merge(
        farms[["farm_name_norm", "timezone", "installed_capacity_kw"]],
        on="farm_name_norm",
        how="left",
        validate="one_to_one",
    )
    return merged.set_index("farm_id").to_dict(orient="index")


def load_calibration_config() -> dict[str, dict[str, object]]:
    payload = json.loads((DATASET_DIR / "sensors_calibration.json").read_text())
    return payload["enterprise_platform"]["deployment_environments"]["system_config"][
        "farms"
    ]


def parse_note_window(line: str, year: int) -> tuple[datetime, datetime] | None:
    patterns = (
        re.compile(
            r"on the (\d{1,2})(?:st|nd|rd|th)? of ([A-Za-z]+) from (\d{2}:\d{2}) to (\d{2}:\d{2})",
            re.IGNORECASE,
        ),
        re.compile(
            r"on ([A-Za-z]+) (\d{1,2})(?:st|nd|rd|th)?, starting at (\d{2}:\d{2}) and finishing at (\d{2}:\d{2})",
            re.IGNORECASE,
        ),
        re.compile(
            r"on ([A-Za-z]+) (\d{1,2})(?:st|nd|rd|th)? from (\d{2}:\d{2}) to (\d{2}:\d{2})",
            re.IGNORECASE,
        ),
    )
    for index, pattern in enumerate(patterns):
        match = pattern.search(line)
        if not match:
            continue
        if index == 0:
            day = int(match.group(1))
            month = MONTHS[match.group(2).lower()]
            start_time = match.group(3)
            end_time = match.group(4)
        else:
            month = MONTHS[match.group(1).lower()]
            day = int(match.group(2))
            start_time = match.group(3)
            end_time = match.group(4)
        start = datetime.strptime(f"{year}-{month:02d}-{day:02d} {start_time}", "%Y-%m-%d %H:%M")
        end = datetime.strptime(f"{year}-{month:02d}-{day:02d} {end_time}", "%Y-%m-%d %H:%M")
        return start, end
    return None


def parse_maintenance_windows(
    farm_metadata: dict[str, dict[str, object]],
) -> dict[str, list[tuple[datetime, datetime]]]:
    name_to_farm_id = {
        str(meta["farm_name_norm"]): farm_id for farm_id, meta in farm_metadata.items()
    }
    normalized_names = sorted(name_to_farm_id, key=len, reverse=True)
    windows: dict[str, list[tuple[datetime, datetime]]] = defaultdict(list)
    notes_path = DATASET_DIR / "maintenance_notes.txt"
    for raw_line in notes_path.read_text().splitlines():
        line = raw_line.strip()
        if "COMPLETED" not in line or "CANCELLED" in line:
            continue
        line_norm = normalize_name(line)
        farm_id = None
        for farm_name_norm in normalized_names:
            if farm_name_norm in line_norm:
                farm_id = name_to_farm_id[farm_name_norm]
                break
        if farm_id is None:
            continue
        window = parse_note_window(line, REPORT_START_UTC.year)
        if window is not None:
            windows[farm_id].append(window)
    return windows


def cadence_hours(local_timestamps: list[datetime]) -> float:
    unique_sorted = sorted(set(local_timestamps))
    deltas = [
        (current - previous).total_seconds() / 3600.0
        for previous, current in zip(unique_sorted, unique_sorted[1:])
        if current > previous
    ]
    if not deltas:
        return 0.0
    return Counter(deltas).most_common(1)[0][0]


def reading_in_windows(
    timestamp_local: datetime, windows: list[tuple[datetime, datetime]]
) -> bool:
    return any(start <= timestamp_local < end for start, end in windows)


def answer() -> dict[str, int]:
    farm_metadata = load_farm_metadata()
    calibration_config = load_calibration_config()
    maintenance_windows = parse_maintenance_windows(farm_metadata)
    results: dict[str, int] = {}

    for farm_id, meta in farm_metadata.items():
        production_path = DATASET_DIR / f"production_{farm_id}.csv"
        encoding = sniff_encoding(production_path)
        delimiter = detect_delimiter(production_path, encoding)
        frame = pd.read_csv(
            production_path,
            skiprows=3,
            sep=delimiter,
            encoding=encoding,
            dtype=str,
            keep_default_na=False,
        ).drop_duplicates()

        timestamp_column = frame.columns[0]
        farm_config = calibration_config[farm_id]
        value_column = farm_config["calibration_data"]["value_column_name"]
        calibration_offset = float(farm_config["calibration_data"]["calibration_offset"])
        reading_type = str(farm_config["sensor_info"]["reading_type"]).lower()
        unit = str(farm_config["sensor_info"]["unit"]).lower()
        timezone_name = str(meta["timezone"])
        installed_capacity_kw = float(meta["installed_capacity_kw"])

        parsed_local_timestamps = [
            timestamp
            for timestamp in (parse_timestamp(value) for value in frame[timestamp_column])
            if timestamp is not None
        ]
        step_hours = cadence_hours(parsed_local_timestamps)

        safety_windows: list[tuple[datetime, datetime]] = []
        for _, row in frame.iterrows():
            timestamp_local = parse_timestamp(row[timestamp_column])
            if timestamp_local is None:
                continue
            temperature = parse_number(row.get("inverter_temperature_C", ""), delimiter)
            if temperature is not None and temperature > 85.0:
                safety_windows.append(
                    (timestamp_local, timestamp_local + timedelta(minutes=45))
                )

        total_kwh = 0.0
        zone = ZoneInfo(timezone_name)
        max_energy_per_reading_kwh = (
            installed_capacity_kw * step_hours * PHYSICAL_HEADROOM
            if step_hours > 0
            else float("inf")
        )
        max_power_per_reading_kw = installed_capacity_kw * PHYSICAL_HEADROOM

        for _, row in frame.iterrows():
            timestamp_local = parse_timestamp(row[timestamp_column])
            if timestamp_local is None:
                continue
            raw_value = parse_number(row.get(value_column, ""), delimiter)
            if raw_value is None:
                continue
            if reading_in_windows(timestamp_local, maintenance_windows.get(farm_id, [])):
                continue
            if any(
                spike_time < timestamp_local < shutdown_end
                for spike_time, shutdown_end in safety_windows
            ):
                continue

            true_value = raw_value - calibration_offset
            if true_value < 0:
                continue

            timestamp_utc = timestamp_local.replace(tzinfo=zone).astimezone(timezone.utc)
            if not (REPORT_START_UTC <= timestamp_utc < REPORT_END_UTC):
                continue

            if reading_type == "power":
                if true_value > max_power_per_reading_kw:
                    continue
                total_kwh += true_value * step_hours
            else:
                reading_kwh = true_value * UNIT_TO_KWH[unit]
                if reading_kwh > max_energy_per_reading_kwh:
                    continue
                total_kwh += reading_kwh

        results[farm_id] = round(total_kwh)

    return results


if __name__ == "__main__":
    with Path("/app/answer.json").open("w") as handle:
        json.dump(answer(), handle, default=list)
